import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.135.0/+esm";
import { gsap } from "https://cdn.jsdelivr.net/npm/gsap@3.8.0/+esm";
import { GLTFLoader } from "https://cdn.jsdelivr.net/npm/three@0.135.0/examples/jsm/loaders/GLTFLoader.js/+esm";

class World {
  async loadShader(path) {
    const res = await fetch(path);
    if (!res.ok) throw new Error(`Failed to load ${path}: ${res.status}`);
    return await res.text();
  }

  async init() {
    this.vertexShader = await this.loadShader("./shaders/vertex.glsl");
    this.fragmentShader = await this.loadShader("./shaders/fragment.glsl");
    this.vertexShader1 = await this.loadShader("./shaders/vertex1.glsl");
    this.fragmentShader1 = await this.loadShader("./shaders/fragment1.glsl");

    await this.addToScene();
  }

  constructor({
    canvas,

    width,

    height,

    cameraPosition,

    fieldOfView = 75,

    nearPlane = 0.1,

    farPlane = 100,
  }) {
    this.parameters = {
      count: 1500,

      max: 12.5 * Math.PI,

      a: 2,

      c: 4.5,
    };

    this.textureLoader = new THREE.TextureLoader();

    this.scene = new THREE.Scene();

    // Background color or texture
    // this.scene.background = new THREE.Color(0x16000a);   // Default background color (black)
    this.bgTextures = { mobile: null, desktop: null };

    this.bgRequested = { mobile: false, desktop: false };

    this.setBackground();

    this.clock = new THREE.Clock();

    this.data = 0;

    this.time = { current: 0, t0: 0, t1: 0, t: 0, frequency: 0.0005 };

    this.angle = { x: 0, z: 0 };

    this.width = width || window.innerWidth;

    this.height = height || window.innerHeight;

    this.aspectRatio = this.width / this.height;

    this.fieldOfView = fieldOfView;

    this.camera = new THREE.PerspectiveCamera(
      fieldOfView,

      this.aspectRatio,

      nearPlane,

      farPlane,
    );

    this.camera.position.set(
      cameraPosition.x,

      cameraPosition.y,

      cameraPosition.z,
    );

    this.scene.add(this.camera);

    this.renderer = new THREE.WebGLRenderer({
      canvas,

      antialias: true,
    });

    this.pixelRatio = Math.min(window.devicePixelRatio, 2);

    this.renderer.setPixelRatio(this.pixelRatio);

    this.renderer.setSize(this.width, this.height);

    this.timer = 0;

    // Start the loop even if something failed to load, so the rest of the scene still renders
    this.init()
      .catch((err) => console.error(err))
      .finally(() => this.loop());

    this.addButton();

    this.render();

    this.listenToResize();

    this.listenToMouseMove();
  }

  start() { }

  render() {
    this.renderer.render(this.scene, this.camera);

    this.composer && this.composer.render();
  }

  loop() {
    this.time.elapsed = this.clock.getElapsedTime();

    // delta is negative (previous - current) and every animation is tuned to that sign,
    // so clamp from below to avoid a big jump after the tab was hidden
    this.time.delta = Math.max(
      -60,

      (this.time.current - this.time.elapsed) * 1000,
    );

    if (this.analyser && this.isRunning) {
      this.time.t = this.time.elapsed - this.time.t0 + this.time.t1;

      this.data = this.analyser.getAverageFrequency();

      this.data *= this.data / 2000;

      this.angle.x += this.time.delta * 0.001 * 0.63;

      this.angle.z += this.time.delta * 0.001 * 0.39;

      const justFinished = this.isRunning && !this.sound.isPlaying;

      if (justFinished) {
        this.time.t1 = this.time.t;

        this.audioBtn.disabled = false;

        this.isRunning = false;

        const tl = gsap.timeline();

        this.angle.x = 0;

        this.angle.z = 0;

        this.cameraReturning = true;

        tl.to(this.camera.position, {
          x: 0,

          z: 4.5,

          duration: 4,

          ease: "expo.in",

          onComplete: () => {
            this.cameraReturning = false;
          },
        });

        tl.to(this.audioBtn, {
          opacity: () => 1,

          duration: 1,

          ease: "power1.out",
        });
      } else {
        this.camera.position.x = Math.sin(this.angle.x) * this.parameters.a;

        this.camera.position.z = Math.min(
          Math.max(Math.cos(this.angle.z) * this.parameters.c, 1.75),

          6.5,
        );
      }
    }

    this.camera.lookAt(this.scene.position);

    if (this.heartMaterial) {
      this.heartMaterial.uniforms.uTime.value +=
        this.time.delta * this.time.frequency * (1 + this.data * 0.2);
    }

    if (this.model) {
      this.model.rotation.y -= 0.0005 * this.time.delta * (1 + this.data);
    }

    if (this.snowMaterial) {
      this.snowMaterial.uniforms.uTime.value +=
        this.time.delta * 0.0004 * (1 + this.data);
    }

    this.render();

    this.time.current = this.time.elapsed;

    requestAnimationFrame(this.loop.bind(this));
  }

  listenToResize() {
    window.addEventListener("resize", () => {
      this.width = window.innerWidth;

      this.height = window.innerHeight;

      // Update camera

      this.camera.aspect = this.width / this.height;

      this.camera.updateProjectionMatrix();

      this.renderer.setSize(this.width, this.height);

      this.setBackground();
    });
  }

  listenToMouseMove() {
    window.addEventListener("mousemove", (e) => {
      // The camera follows the music orbit (and its return tween) while those run
      if (this.isRunning || this.cameraReturning) return;

      const x = e.clientX;

      const y = e.clientY;

      // Camera moves opposite to the cursor on both axes (screen y points down, world y up)
      gsap.to(this.camera.position, {
        x: gsap.utils.mapRange(0, window.innerWidth, 0.2, -0.2, x),

        y: gsap.utils.mapRange(0, window.innerHeight, -0.2, 0.2, y),

        overwrite: "auto",
      });
    });
  }

  addHeart() {
    this.heartMaterial = new THREE.ShaderMaterial({
      vertexShader: this.vertexShader,
      fragmentShader: this.fragmentShader,
      uniforms: {
        uTime: { value: 0 },

        uSize: { value: 0.2 },

        uTex: {
          value: new THREE.TextureLoader().load(
            // "https://assets.codepen.io/74321/heart.png",
            "./images/heart.png",
          ),
        },
      },

      depthWrite: false,

      blending: THREE.AdditiveBlending,

      transparent: true,
    });

    const count = this.parameters.count; //2000

    const scales = new Float32Array(count * 1);

    const colors = new Float32Array(count * 3);

    const speeds = new Float32Array(count);

    const randoms = new Float32Array(count);

    const randoms1 = new Float32Array(count);

    const colorChoices = [
      "white",

      "red",

      "pink",

      "crimson",

      "hotpink",

      "green",

      "aquamarine",

      "blue",
    ];

    const squareGeometry = new THREE.PlaneGeometry(1, 1);

    this.instancedGeometry = new THREE.InstancedBufferGeometry();

    Object.keys(squareGeometry.attributes).forEach((attr) => {
      this.instancedGeometry.attributes[attr] = squareGeometry.attributes[attr];
    });

    this.instancedGeometry.index = squareGeometry.index;

    this.instancedGeometry.maxInstancedCount = count;

    for (let i = 0; i < count; i++) {
      const phi = Math.random() * Math.PI * 2;

      const i3 = 3 * i;

      randoms[i] = Math.random();

      randoms1[i] = Math.random();

      scales[i] = Math.random() * 0.35;

      const colorIndex = Math.floor(Math.random() * colorChoices.length);

      const color = new THREE.Color(colorChoices[colorIndex]);

      colors[i3 + 0] = color.r;

      colors[i3 + 1] = color.g;

      colors[i3 + 2] = color.b;

      speeds[i] = Math.random() * this.parameters.max;
    }

    this.instancedGeometry.setAttribute(
      "random",

      new THREE.InstancedBufferAttribute(randoms, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "random1",

      new THREE.InstancedBufferAttribute(randoms1, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "aScale",

      new THREE.InstancedBufferAttribute(scales, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "aSpeed",

      new THREE.InstancedBufferAttribute(speeds, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "aColor",

      new THREE.InstancedBufferAttribute(colors, 3, false),
    );

    this.heart = new THREE.Mesh(this.instancedGeometry, this.heartMaterial);

    console.log(this.heart);

    this.scene.add(this.heart);
  }

  async addToScene() {
    // A missing model should not prevent the particles from showing
    try {
      await this.addModel();
    } catch (err) {
      console.error("Failed to load heart model", err);
    }
    this.addHeart();
    this.addSnow();
  }

  async addModel() {
    this.model = await this.loadObj(
      // "https://assets.codepen.io/74321/heart.glb",
      "./models/heart.glb",
    );

    this.model.scale.set(0.01, 0.01, 0.01);

    const grow = () => {
      gsap.to(this.model.scale, {
        x: 0.35,

        y: 0.35,

        z: 0.35,

        duration: 1.5,

        ease: "Elastic.easeOut",
      });
    };

    this.model.material = new THREE.MeshMatcapMaterial({
      matcap: this.textureLoader.load(
        // "https://assets.codepen.io/74321/3.png",
        "./images/3.png",

        grow,

        undefined,

        // Still show the heart (untextured) if the matcap fails to load
        (err) => {
          console.error(err);
          grow();
        },
      ),

      color: "#fff",
    });

    this.scene.add(this.model);
  }

  addButton() {
    this.audioBtn = document.querySelector("button");

    this.audioBtn.addEventListener("click", () => {
      this.audioBtn.disabled = true;

      if (this.analyser) {
        this.sound.play();

        this.time.t0 = this.time.elapsed;

        this.data = 0;

        this.isRunning = true;

        gsap.killTweensOf(this.camera.position);

        gsap.to(this.audioBtn, {
          opacity: 0,
          duration: 1,
          ease: "power1.out",
        });
      } else {
        this.loadMusic()
          .then(() => {
            console.log("music loaded");

            // Progress events may not fade the button fully (e.g. no Content-Length)
            gsap.to(this.audioBtn, {
              opacity: 0,
              duration: 1,
              ease: "power1.out",
              overwrite: true,
            });
          })
          .catch((err) => {
            console.error("Failed to load music", err);

            // Let the user try again
            this.audioBtn.disabled = false;

            gsap.to(this.audioBtn, {
              opacity: 1,
              duration: 1,
              ease: "power1.out",
              overwrite: true,
            });
          });
      }
    });
  }

  loadObj(path) {
    const loader = new GLTFLoader();

    return new Promise((resolve, reject) => {
      loader.load(
        path,

        (response) => {
          resolve(response.scene.children[0]);
        },

        (xhr) => { },

        reject,
      );
    });
  }

  loadMusic() {
    return new Promise((resolve, reject) => {
      const listener = new THREE.AudioListener();

      this.camera.add(listener);

      this.sound = new THREE.Audio(listener);

      const audioLoader = new THREE.AudioLoader();

      audioLoader.load(
        // File nhạc mp3
        // "https://res.cloudinary.com/dmnxeusyw/video/upload/v1668310333/sharecs.net/music_ji3iak.mp3",
        "./sounds/inlove.mp3",

        (buffer) => {
          this.sound.setBuffer(buffer);

          this.sound.setLoop(false);

          this.sound.setVolume(0.5);

          this.sound.play();

          this.analyser = new THREE.AudioAnalyser(this.sound, 32);

          const data = this.analyser.getAverageFrequency();

          this.isRunning = true;

          this.time.t0 = this.time.elapsed;

          gsap.killTweensOf(this.camera.position);

          resolve(data);
        },

        (progress) => {
          // total is 0 when the server sends no Content-Length
          if (!progress.lengthComputable || !progress.total) return;

          gsap.to(this.audioBtn, {
            opacity: () => 1 - progress.loaded / progress.total,

            duration: 1,

            ease: "power1.out",
          });
        },

        (error) => {
          // Undo the setup so the next click starts from scratch
          this.camera.remove(listener);

          this.sound = null;

          reject(error);
        },
      );
    });
  }

  addSnow() {
    this.snowMaterial = new THREE.ShaderMaterial({
      vertexShader: this.vertexShader1,
      fragmentShader: this.fragmentShader1,

      uniforms: {
        uTime: { value: 0 },

        uSize: { value: 0.3 },

        uTex: {
          value: new THREE.TextureLoader().load(
            // "https://assets.codepen.io/74321/heart.png",
            "./images/heart.png",
          ),
        },
      },

      depthWrite: false,

      blending: THREE.AdditiveBlending,

      transparent: true,
    });

    const count = 550;

    const scales = new Float32Array(count * 1);

    const colors = new Float32Array(count * 3);

    const phis = new Float32Array(count);

    const randoms = new Float32Array(count);

    const randoms1 = new Float32Array(count);

    const colorChoices = [
      "red",
      "pink",
      "hotpink",
      "green",
      "aquamarine",
      "blue",
    ];

    const squareGeometry = new THREE.PlaneGeometry(1, 1);

    this.instancedGeometry = new THREE.InstancedBufferGeometry();

    Object.keys(squareGeometry.attributes).forEach((attr) => {
      this.instancedGeometry.attributes[attr] = squareGeometry.attributes[attr];
    });

    this.instancedGeometry.index = squareGeometry.index;

    this.instancedGeometry.maxInstancedCount = count;

    for (let i = 0; i < count; i++) {
      const phi = (Math.random() - 0.5) * 10;

      const i3 = 3 * i;

      phis[i] = phi;

      randoms[i] = Math.random();

      randoms1[i] = Math.random();

      scales[i] = Math.random() * 0.35;

      const colorIndex = Math.floor(Math.random() * colorChoices.length);

      const color = new THREE.Color(colorChoices[colorIndex]);

      colors[i3 + 0] = color.r;

      colors[i3 + 1] = color.g;

      colors[i3 + 2] = color.b;
    }

    this.instancedGeometry.setAttribute(
      "phi",

      new THREE.InstancedBufferAttribute(phis, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "random",

      new THREE.InstancedBufferAttribute(randoms, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "random1",

      new THREE.InstancedBufferAttribute(randoms1, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "aScale",

      new THREE.InstancedBufferAttribute(scales, 1, false),
    );

    this.instancedGeometry.setAttribute(
      "aColor",

      new THREE.InstancedBufferAttribute(colors, 3, false),
    );

    this.snow = new THREE.Mesh(this.instancedGeometry, this.snowMaterial);

    this.scene.add(this.snow);
  }

  setBackground() {
    const key = window.innerWidth < 768 ? "mobile" : "desktop";
    this.bgKey = key;

    if (this.bgTextures[key]) {
      this.scene.background = this.bgTextures[key];
      return;
    }

    // Decrypt each size only once, the first time it is needed
    if (this.bgRequested[key]) return;
    this.bgRequested[key] = true;

    const fallback = () => {
      if (this.bgKey === key) this.scene.background = new THREE.Color(0x16000a);
    };

    decryptImage(key)
      .then((blob) => {
        const url = URL.createObjectURL(blob);

        this.textureLoader.load(
          url,
          (texture) => {
            URL.revokeObjectURL(url);
            this.bgTextures[key] = texture;
            if (this.bgKey === key) this.scene.background = texture;
          },
          undefined,
          () => {
            URL.revokeObjectURL(url);
            fallback();
          }
        );
      })
      .catch((e) => {
        console.warn("Không giải mã được ảnh nền", e);
        fallback();
      });
  }
}

async function decryptImage(size) {
  // Web Crypto only exists on HTTPS pages (and localhost)
  if (!window.crypto.subtle) throw new Error("Decrypting needs HTTPS (or localhost)");

  const backgrounds = encryptedBackgrounds();

  const toBytes = (base64) =>
    Uint8Array.from(atob(base64.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));

  const key = await crypto.subtle.importKey("raw", toBytes(backgrounds.key), "AES-GCM", false, ["decrypt"]);

  // Layout written by tools/encrypt-background.js: iv (12 bytes) + ciphertext + tag
  const payload = toBytes(backgrounds[size]);
  const image = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: payload.subarray(0, 12) },
    key,
    payload.subarray(12),
  );

  return new Blob([image], { type: "image/jpeg" });
}

const world = new World({
  canvas: document.querySelector("canvas.webgl"),
  cameraPosition: { x: 0, y: 0, z: 4.5 },
});

// BEGIN ENCRYPTED BACKGROUNDS (generated by tools/encrypt-background.js, do not edit by hand)
// AES-256-GCM: each image is base64 of iv + ciphertext + tag, decrypted with `key`
function encryptedBackgrounds() {
  return {
    key: "mGCEdjny_uRdt_QgscVChuF7zZpHxMnYo_olqomBvC0",
    desktop: "",
    mobile: "",
  };
}
// END ENCRYPTED BACKGROUNDS
